from unicodedata import normalize

def transliterate(text):
    return ''.join(c for c in normalize('NFKD', text) if c.isascii())


def parameterize(string, separator='-'):
    # Transliterate the text
    transliterated = transliterate(string)

    # Replace non-ASCII letters, digits, '-', and '_' with the separator
    result = ''
    i = 0
    while i < len(transliterated):
        if transliterated[i].isalnum() or transliterated[i] in '-_':
            result += transliterated[i]
            i += 1
        else:
            start = i
            while i < len(transliterated) and not transliterated[i].isalnum() and transliterated[i] not in '-_':
                i += 1
            result += separator * (i - start)

    # Collapse consecutive separators and remove leading/trailing separators
    result = separator.join(result.split(separator)).strip(separator)

    # Lower-case the result
    return result.lower()
